INSERT INTO bot_installations(bot_key) VALUES ('default') ON CONFLICT DO NOTHING;
CREATE TABLE users (id BIGINT PRIMARY KEY, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE channels (id BIGINT PRIMARY KEY, title TEXT NOT NULL, auto_approve BOOLEAN NOT NULL DEFAULT false, welcome TEXT NOT NULL DEFAULT 'Welcome!', live_text TEXT);
CREATE TABLE admins (id BIGINT PRIMARY KEY);
CREATE TABLE messages (id UUID PRIMARY KEY, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE media (id UUID PRIMARY KEY, message_id UUID NOT NULL REFERENCES messages, file_id TEXT NOT NULL, kind TEXT NOT NULL);
CREATE TABLE buttons (id UUID PRIMARY KEY, message_id UUID NOT NULL REFERENCES messages, label TEXT NOT NULL, url TEXT NOT NULL);
CREATE TABLE templates (id UUID PRIMARY KEY, name TEXT NOT NULL UNIQUE, message_id UUID NOT NULL REFERENCES messages);
CREATE TABLE welcome_steps (channel_id BIGINT REFERENCES channels, position INT NOT NULL, delay_seconds INT NOT NULL CHECK(delay_seconds BETWEEN 0 AND 240), text TEXT NOT NULL, PRIMARY KEY(channel_id,position));
CREATE TABLE join_requests (update_id BIGINT PRIMARY KEY, channel_id BIGINT NOT NULL REFERENCES channels, user_id BIGINT NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE live_events (id BIGSERIAL PRIMARY KEY, update_id BIGINT UNIQUE, channel_id BIGINT REFERENCES channels, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE campaigns (id UUID PRIMARY KEY, text TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'RUNNING' CHECK(state IN ('RUNNING','PAUSED','CANCELLED','COMPLETED')), cursor BIGINT NOT NULL DEFAULT 0, cutoff TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE jobs (id UUID PRIMARY KEY, dedupe TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, payload JSONB NOT NULL, state TEXT NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','RUNNING','DONE','DEAD','UNKNOWN')), due_at TIMESTAMPTZ NOT NULL DEFAULT now(), attempts INT NOT NULL DEFAULT 0, lease_until TIMESTAMPTZ, lease_token UUID, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX jobs_due ON jobs(kind,due_at) WHERE state='PENDING';
ALTER TABLE jobs ADD COLUMN signal_after TIMESTAMPTZ NOT NULL DEFAULT now();
CREATE INDEX jobs_expired ON jobs(lease_until) WHERE state='RUNNING';
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, action TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
